// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";
import {IERC165} from "../src/GameItems.sol";
import {IERC1155} from "../src/GameItems.sol";
import {IERC1155MetadataURI} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(uint256 k) public {
        // The contract claims support for exactly its advertised interfaces.
        // k selects which advertised interface we query; the rule is universal:
        // for ANY advertised interface (any k in [0,2]), supportsInterface is true.
        bytes4[3] memory advertised = [
            type(IERC165).interfaceId,
            type(IERC1155).interfaceId,
            type(IERC1155MetadataURI).interfaceId
        ];
        uint256 idx = bound(k, 0, 2);
        assertTrue(c.supportsInterface(advertised[idx]));
    }
}
